quests[24677] = { id = 24677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flankiert die Verlassenen", description = "Ich danke Euch, {name}. Wir können uns jedoch nicht auf unseren Lorbeeren ausruhen.\n\nWir haben von einem Bergbaudorf erfahren, das derzeit von den Verlassenen besetzt wird. Einige unserer Männer sind zusammen mit Crowleys Tochter zu den nahegelegenen Pferdeställen aufgebrochen, um von dort aus das Kommando zu übernehmen. Liam sollte in Kürze zu ihnen stoßen.\n\nIch bleibe hier und organisiere die letzte Angriffswelle in Gilneas. Sprecht mit Lord Hewell, um Euch ein Pferd zu besorgen, das Euch dorthin bringen kann.", sourceObjective = "Sprecht mit Lord Hewell, um Euch ein Pferd zur Pferdewechselstation zu organisieren, und meldet Euch bei Lorna Crowley.", completion = "Ich bin froh, dass Ihr hier seid, {name}. Wir sind von allen Seiten von den Verlassenen umzingelt und können jede Hilfe brauchen, die wir kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24678] = { id = 24678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knietief", description = "Es ist Zeit, zusammenzupacken, {name}. Die meisten unserer Leute haben es auf die andere Seite geschafft. Jetzt seid Ihr dran.\n\nNehmt diese Fackel, Ihr werdet sie noch brauchen. Im Tunnel wimmelt es nur so von widerlichen Kreaturen der übelsten Sorte, die Euch in die Knie beißen werden. Verwendet die Fackel, um sie Euch fern zu halten.\n\nSprecht auf der anderen Seite mit Krennan.", sourceObjective = "Nehmt die halb abgebrannte Fackel, um an die andere Seite des Tunnels unter Gilneas zu gelangen.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid hier, {name}. Die meisten haben es auf die andere Seite geschafft, aber jetzt sitzen wir hier, umringt von unseren eigenen… Toten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24679] = { id = 24679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Patriarchen", description = "Ihr habt es geschafft, {name}. Sogar in Zeiten wie diesen müssen wir unseren Toten die Ehre erweisen.\n\nNehmt diese Opfergaben und legt sie auf Aderics Grab.\n\nHoffen wir, dass sie ausreichen, um die Geister unserer Ahnen zu besänftigen.", sourceObjective = "Legt die gesegneten Opfergaben auf Aderics Grab.", completion = "Es ist vollbracht, {name}. Die Toten versinken wieder in ewigen Schlaf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24680] = { id = 24680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kielwasser", description = "Wir haben vielleicht unsere Stadt verloren, aber zumindest scheinen die Toten uns vergeben zu haben.\n\nSchließt Euch den restlichen Überlebenden in Kielwasser an.\n\nIch bin mir sicher, dass es noch viel zu tun gibt, bevor wir das Gröbste überstanden haben. Genn ist noch nicht eingetroffen, also nehme ich an, dass Lord Crowley dort das Sagen hat.", sourceObjective = "Sprecht mit Lord Darius Crowley in Kielwasser in Gilneas.", completion = "Schön, Euch wiederzusehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24681] = { id = 24681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Verbündete, aber wir auch", description = "Die Nachtelfen haben ihr Versprechen gehalten. Sie haben uns Schiffe geschickt und bieten uns Schutz in ihrem Land.\n\nLeider sind aber auch die Verbündeten der Verlassenen eingetroffen.\n\nDie Orcs rücken immer näher und das Kanonenboot der Horde schneidet unseren Leuten auf den Transportschiffen den Weg in die Sicherheit ab.\n\nDie Druiden versuchen, den Feind zurückzuhalten, aber lange werden sie nicht durchhalten. Zum Glück haben die Elfenschiffe Belagerungswaffen mitgebracht. Nehmt eine von den Glevenschleudern und tretet dem Feind gegenüber!", sourceObjective = "Benutzt die Glevenschleuder der Nachtelfen, um 40 orcische Räuber, 8 Vorhuten des Wolfschlunds und 4 orcische Kriegsmaschinen zu vernichten.", completion = "Es ist fast vorbei, {name}. Nur noch ein Hindernis steht zwischen uns und unserem Überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zur Grube von Saron.", completion = "Unfähige Narren! So langsam frage ich mich, ob sich überhaupt einer von diesen Knilchen vom Turnier als nützlich erweisen wird. Vielleicht könnt Ihr mich ja vom Gegenteil überzeugen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Lady Jaina Prachtmeer in der Grube von Saron.", completion = "Ich habe diesen Geißelfürsten unterschätzt und meine Leute haben dafür bezahlt. Immer, wenn ich denke, dass mich keine größere Schuld mehr an Arthas' Verrat treffen kann, belehrt er mich eines Besseren.\n\nWir müssen weitermachen! Ihr Opfer darf nicht bedeutungslos sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[24684] = { id = 24684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fux im Hühnerstall", description = "<Gann packt Euch mit blutverkrusteter Hand.>\n\nMeine Wunden sind schwerwiegend, aber ich werde nicht aufgeben, bis die Zwerge von Bael Modan für ihre Verbrechen bezahlt haben. <Keuchen> Wir haben während unseres letzten Überfalls einen Mann in ihre Festung hineingeschmuggelt. Einen Saboteur der Goblins: Fux Schattenschleicher. \n\nStartet ein Ablenkungsmanöver vor den Toren, tötet, wen immer Ihr könnt - und dann schleicht Euch in die Festung Bael'dun im Süden und findet Fux.\n\nDiese Festung <hust> kann nur von innen heraus zerstört werden und Fux schafft das nicht alleine.", sourceObjective = "Begebt Euch in die Burg Bael'dun und tötet 10 Zwerge von Bael'dun (Scharfschützen, Soldaten oder Offiziere). Dann findet Fux Schattenschleicher, der sich irgendwo dort drinnen versteckt hält.", completion = "Ihr macht gute Arbeit, {class}. Der Aufstand, den Ihr am Eingang zur Burg angezettelt habt, lässt die Zwerge völlig kopflos herumrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24685] = { id = 24685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenfestung", description = "Ich weiß nicht, ob Ihr es auf Eurem Weg hinein bemerkt habt, aber die ganze Burg wurde um eine riesige Kanone herum erbaut. Wenn wir nur das Munitionslager finden könnten, dann wären wir in der Lage, hier alles in die Luft zu jagen und es wäre so einfach, wie ein Handkuss!\n\nNur, um das herauszufinden brauche ich die Bauzeichnung der Burg und bisher konnte ich die noch nicht stehlen.\n\nSucht nach den Plänen auf der untersten Etage, direkt die Treppe hier hinunter.", sourceObjective = "Bringt den Plan der Burg Bael'dun an Euch.", progress = "Gebt mir den Plan, schnell! Die Zeit wird knapp.\n\nHauptsächlich, weil ich meine Verkleidung gegessen habe.", completion = "Schauen wir mal, schauen wir mal...\n\nAnscheinend werden die Artilleriegranaten hier vorgefertigt und dann in das gesicherte Lager gebracht...\n\n<Fux reibt sich die Hände.>\n\n{name}, seid Ihr bereit, etwas in die Luft zu jagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24686] = { id = 24686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgespült", description = "Die Blutblüten in Un'Goro durchlaufen einen faszinierenden Lebenszyklus.\n\nDiese Bäume hier vor uns tragen Samen, die hinunter in den Fluss fallen, wenn sie reifen. Die Strömung trägt die Samen dann nach Norden, wo die Saat aufgeht - beinahe wie ein Ei - und eine neugeborene Blutblüte schlüpft.\n\nIch brauche diese Samen für meine Forschung. Nehmt dieses Netz und schöpft damit die leuchtend orangefarbenen Samen aus dem Fluss. Ihr werdet unter Wasser nach ihnen suchen müssen.", sourceObjective = "Verwendet Garls Netz um 4 Blutblütensamen einzufangen.", progress = "Habt Ihr schon alle Samen?", completion = "Hmm... ja, diese Samen dürften ausreichen. Der Zirkel des Cenarius dankt Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24687] = { id = 24687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sträuße des Todes", description = "Die erste Phase des Lebenszyklus der Blutblüten kennt Ihr bereits: die schwimmenden Samen. Die nächste Phase ist aber nicht so zahm: die Rudel Halbwüchsiger.\n\nWenn die Blutblüten geschlüpft sind, bilden sie schnell Banden und ziehen gemeinsam umher, wodurch sie ihre Schwächen mit einer überwältigenden Mehrheit ausgleichen. Diese Banden junger Peitscher bleiben meistens unter sich, aber wenn man auch nur einen einzelnen von ihnen angreift, hat man es schnell mit allen zu tun.\n\nGebietet ihnen im Interesse unserer Sicherheit und der Sicherheit Anderer Einhalt. Ihr findet sie hier in der Nähe, im Westen und Norden.", sourceObjective = "Tötet 6 Rudel halbwüchsiger Blutblüten.", completion = "Ihr kehrt siegreich zurück. Gut, gut... Vielleicht wird der Krater nun etwas sicherer für Reisende sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24688] = { id = 24688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Aliri", description = "Ihr habt bereits einen meiner neuen Schüler kennengelernt, den jungen Worgen namens Garl. Mein anderer Schüler ist der Troll Zen'Aliri. Er hat zur Zeit sein Zelt bei den Entdeckern in Marschalls Expedition westlich von hier.\n\nBringt ihm diese Ergebnisse, {name}, und sagt ihm, er soll sie gründlich lesen.", sourceObjective = "Meldet Euch bei Zen'Aliri in Marschalls Wehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[24689] = { id = 24689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Norden fließen", description = "Ithis Mondwärter ist der Nachtelfendruide, der mich in den Zirkel des Cenarius eingeführt hat. Sein Lager liegt nördlich von hier, in der Nähe der Klippen am östlichsten Kraterrand. Folgt dem Strom der Blutblütensamen und ich wette, Ihr werdet ihn dort in der Nähe finden.\n\nMeine Studien beschränken sich lediglich auf die Samen und andere Reagenzien, er jedoch geht viel fortgeschritteneren Dingen nach. Falls Ihr neugierig geworden seid und mehr über die Flora Un'Goros erfahren wollt, solltet Ihr Euch jetzt an ihn wenden.", sourceObjective = "Meldet Euch bei Ithis Mondwärter in den Aufwühlenden Gärten.", completion = "Ahh... Hat Garl Euch geschickt? Wie verlaufen seine Studien? Ich finde, er kann manchmal etwas langsam sein, aber in Bärengestalt sollte man ihn wahrhaftig besser nicht unterschätzen.\n\nNun, es gibt dringendere Dinge, die nach unserer Aufmerksamkeit verlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24690] = { id = 24690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmflamme", description = "Ich mache mir immer noch etwas Gedanken über diese Feuerelementare, {name}. Eine letzte Bitte: Begebt Euch zur Spitze des Feuersäulengrats und tötet denjenigen von ihnen, den sie Sturmflamme nennen. Er ist der größte und stärkste der Feuerelementare im Krater. Ich werde viel besser schlafen, wenn er aus dem Weg ist.", sourceObjective = "Tötet Sturmflamme.", completion = "Endlich ist Sturmflamme vernichtet. Danke, {name}... Er hat mich zur Weißglut gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24691] = { id = 24691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenartige Delikatessen", description = "He <Süßer/Süße>, Interesse, Euch was dazuzuverdienen?\n\nIch weiß aus sicherer Quelle, dass einige Interessengruppen gutes Geld für Silithidenbeine zahlen. Ja, Ihr habt richtig gehört, Silithidenbeine! Anscheinend sind die richtig lecker, wenn man sie richtig zubereitet. Die sind wie unterirdische Krebse und leben südlich von hier.\n\nDas Problem ist, dass ich eine ordentliche Menge brauche, um meine Ausgaben abzudecken. Meint Ihr, Ihr könntet mir vielleicht so etwa 8 Dutzend beschaffen?", sourceObjective = "Erhaltet 96 Silithidenbeine.", progress = "Ich brauche eine Menge Beine, weil ich doch für den Versand, das Verladen, das Marketing und so weiter bezahlen muss... Oh und Euch muss ich auch noch bezahlen.", completion = "Hervorragend! Wir sitzen hier auf der Spitze von etwas ganz Großem, {name}. Hier ist Euer Anteil an den garantiert riesigen Profiten.\n\nUnd jetzt auf zu anderen Dingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24692] = { id = 24692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kolossjunge", description = "Wenn Ihr hier seid, um zu helfen, dann könntet Ihr Euch vielleicht einer lauernden Bedrohung annehmen.\n\nIm Süden liegt die Wuchernde Narbe, ein vor Silithiden wimmelnder Außenposten mitten im Dschungel. Ihr könnt ihn gar nicht übersehen.\n\nEiner meiner Kundschafter berichtet, dass die Silithiden einen jungen Koloss in ihrer großen, unterirdischen Zentralkammer beherbergen. Wenn diese Bestie erst einmal herangewachsen ist, soll sie auf Un'Goro losgelassen werden!\n\nSoweit darf es nicht kommen, {name}. Spürt den Koloss auf und tötet ihn.", sourceObjective = "Tötet das Kolossjunge der Gorishi.", completion = "Ihr habt eine außerordentliche Aufgabe vollbracht, {name}. Diese Belobigung habt Ihr Euch wahrhaftig verdient. Vielen Dank und herzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[24693] = { id = 24693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mooshügel", description = "Hier in Marschalls Wehr kann ich eigentlich nicht so viel Preisschneiderei betreiben, ohne dass die Wissenschaftler misstrauisch werden. Es gibt aber noch einen Ort, an dem Ihr mir von Nutzen sein könntet.\n\nMein Geschäftspartner Gremix hat ein Lager im Nordwesten, auf der anderen Seite des Vulkans. Er ist ein gerissener Geschäftsmann und hat sogar ein noch besseres Gespür für Profit als ich. Ich bin sicher, er könnte für Euch Arbeit finden, wenn Ihr Euch noch ein paar Münzen verdienen wollt.", sourceObjective = "Meldet Euch bei Gremix am Mooshügel.", completion = "Nun gut, wenn Quixxil Euch empfohlen hat, dann müsst Ihr wohl in Ordnung sein. In all den Jahren unserer Zusammenarbeit hat mich Quixxil nie fehlgeleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24694] = { id = 24694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse des Formers", description = "<Als Ihr in die Kugel vor Euch blickt, hört Ihr eine Stimme.>\n\nDie Kristallpylonen wurden aktiviert. Eine ausreichende Menge Kristalle wurde gesammelt. Die Bedingungen wurden erfüllt. Wir sind bereit für den Teleport zur Terrasse des Formers.\n\nSprecht mich an, wenn Ihr bereit seid, {race}. Wir werden uns mit der Wächterin beraten.", sourceObjective = "Sprecht mit dem Prüfer von Un'Goro, um zur Terrasse des Formers teleportiert zu werden, und sprecht dann mit Nablya.", completion = "Ich habe Euch beobachtet, {name}. Eure Ankunft war nicht unerwartet.\n\nIn der Tat ist Eure Ankunft hier schon vor einiger Zeit vorherbestimmt worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24695] = { id = 24695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der immer wachsame Blick von oben.", description = "Als mein Meister Khaz'goroth die Welt, die Ihr Azeroth nennt, formte, entwarf er den Un'Goro Krater als ein Gebiet, in dem Experimente stattfinden konnten. Man könnte ihn auch die Petrischale der Titanen nennen.\n\nFalls Ihr weiteres Wissen darüber erlangen wollt, wie wir die Welt beobachten, legt die vier Hebel hinter mir um und besteht meine Prüfungen.", sourceObjective = "Legt die Hebel hinter Nablya um und vollendet ihre Prüfungen.", completion = "Ihr habt unter Beweis gestellt, dass Ihr nicht nur weise, sondern auch behände seid, junger {name}. Ich erteile Euch meinen Segen, Euer neuerlangtes Wissen auf Euren Reisen in die Welt zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24697] = { id = 24697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man Fleisch wieder frisch macht", description = "Ich glaube nicht, dass wir einander schon kennengelernt haben... Ich bin Nolen Tacker, der neue Hauptmann der Wache von Marschalls Expedition. Ich bin außerdem der Koch hier. Da gibt es sogar mehr Überschneidungen, als man denken würde.\n\nIch habe eine spaßige kleine Aufgabe für Euch. Habt Ihr die Stachelgruben entlang der Außenbefestigung des Lagers gesehen? Schaut doch mal, ob Ihr nicht einige der Dinosaurier in der Nähe dazu bringen könnt, in diese Fallen zu tappen. Wenn Ihr dieses verfaulende Fleisch nach ihnen werft, wenn sie nicht hinsehen, werden sie entweder hungrig oder böse werden, was beides in Ordnung ist, solange sie Euch nur in die Gruben folgen!", sourceObjective = "Benutzt die Fetzen verdorbenen Fleisches, um die in der Nähe befindlichen Dinosaurier in die Gruben rund um Marschalls Wehr zu locken.", progress = "Werft das Fleisch und lasst Euch dann von den Dinosauriern in die Gruben folgen. So einfach ist das!", completion = "Ausgezeichnete Arbeit, {name}. Jetzt sind wir ein wenig sicherer vor den Dinosaurierüberfällen... Außerdem habe ich all dieses frische Fleisch, das ich meinen Männern servieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24698] = { id = 24698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologische Abenteuer", description = "He, wollt Ihr meine Dimetrodonwürstchen probieren? Nein? Raptorrisotto? Pterrordaxtacos?\n\nNa gut. Oh, da fällt mir etwas ein! Ich habe hier in der Nähe einen Freund, der Eure Hilfe brauchen könnte. Sein Name ist Funks Nilminer und er ist der oberste archäologische Offizier in Marschalls Expedition. \n\nEr wurde hinaus zu den Heißen Quellen von Golakka im Westen geschickt. Ihr werdet ihn wahrscheinlich am Westufer der Quellen finden.", sourceObjective = "Meldet Euch bei Funks Nilminer bei den Heißen Quellen von Golakka.", completion = "Der gute alte Nolen. Wie geht's dem so? Hoffentlich besser als mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[24699] = { id = 24699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormashh der Klebrige", description = "He, ich hab's! Wir haben es mit den falschen Teergeschöpfen versucht.\n\nGremix hat mir einmal von einer übermäßig großen Teerkreatur erzählt, die ihm über den Weg gelaufen ist. Sie haust in der Nähe der Teergruben weit östlich von hier, südlich vom Fungusfels. Ich wette, je größer diese Kreaturen werden, desto klebriger werden sie! Wir machen schon noch Umsatz, {name}! Vergesst den Schaber nicht!", sourceObjective = "Tötet Gormashh und erhaltet den unglaublich klebrigen Teer.", progress = "Ich zähle auf Euch, {name}. Ich habe mich ziemlich tief für diesen \"Teer als Klebstoff\"-Plan verschuldet und es wäre sehr schade, wenn Ihr mit leeren Händen zurückkehren würdet.", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, wartet mal, meine Hände! Ich bekomme sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, Moment mal! Superklebriger Teerentferner! Da lässt sich das richtige Geld machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24700] = { id = 24700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer zu pflücken", description = "Die Teergruben von Lakkari nördlich von hier bergen einen geheimen Schatz: seltene Blumen, die am Boden der Gruben wachsen. Man nennt sie Teerblüten und schätzt sie für ihre Schönheit und Widerstandsfähigkeit. Es ist schon eine Weile her, seit ich das letzte Mal Teerblüten gesammelt habe, also sollten mittlerweile einige neue Pflanzen am Boden der Gruben nachgewachsen sein. Würdet Ihr ein paar für mich holen?\n\nÜbrigens, viel Spaß beim Teerschwimmen. Das hat überhaupt nichts mit Schwimmen im Wasser gemeinsam.", sourceObjective = "Erhaltet 4 Teerblüten.", progress = "Habt Ihr schon die Teerblüten gesammelt? Ich sehe sie nirgends...", completion = "Ah, da sind sie ja. Ausgezeichnete Arbeit, Hübscher! Hier habt Ihr etwas Gold. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[24701] = { id = 24701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschalls Überbleibsel", description = "Ein Großteil beim Profit machen ist Unverschämtheit. Ihr müsst bereit sein, Euren Nutzen aus dem Unglück anderer zu ziehen. Es läuft alles auf eine Frage hinaus: Wie sehr liebt Ihr Geld?\n\nAls Marschall und seine Truppe ihre Zuflucht im Norden verlassen haben, mussten sie eine Menge Vorräte zurücklassen. Das Zeug ist nicht selten, oder gar besonders wertvoll, aber es liegt dort herum, wenn Ihr gewillt seid, es Euch zu nehmen. Sein Lager ist oben zwischen den Klippen im Norden.\n\nOh, und nehmt Euch in Acht vor was auch immer die anderen in die Flucht geschlagen hat.", sourceObjective = "Erhaltet 10 weggeworfene Vorräte.", progress = "Habt Ihr etwas Brauchbares gefunden?", completion = "Das ist zwar ein Haufen Ramsch, aber dafür ist es ein Haufen KOSTENLOSER RAMSCH und das ist das einzige, was für mich zählt.\n\nNaja, weitestgehend kostenlos. Hier ist Euer Anteil. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[24702] = { id = 24702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ruht Dadanga", sourceObjective = "Erhaltet 10 Blutblütensprösslinge.", progress = "Verlässliches Lasttier und treuer Freund.\n\nStarb kurz nach dem Kataklysmus. Er hatte laute Geräusche immer verabscheut.\n\nAnstelle von Blumen legt bitte ein paar Blutblütensprösslinge nieder. Als er noch am Leben war, hatte er nichts lieber.", completion = "<Ihr verspürt beinahe so etwas wie eine Welle der Dankbarkeit als Ihr die Blutblütensprösslinge auf das Grab legt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24703] = { id = 24703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wichtige Lektion", description = "Heda, <Reisender/Reisende>! Ihr müsst wissen, dass Ihr das Lager des Maximillian von Nordhain betreten habt. Vielleicht habt Ihr schon Geschichten über meine vielen Heldentaten gehört? Ich kann es Euch ansehen, dass dem so ist. Dieser Funke der Erinnerung huscht über Euer Antlitz wie das Spiegelbild der Weißen Dame über den Steinhügelsee.\n\nEs ist offensichtlich, dass Ihr nach Abenteuern sucht. Da Ihr einigermaßen fähig zu sein scheint, und durch und durch wohlwollend, möchte ich Euch anbieten, mein Knappe zu werden.", sourceObjective = "Sprecht mit Maximillian von Nordhain und erfahrt mehr darüber, wie man Knappe wird.", completion = "Ihr erfreut mich, {name}. Von heute an seid Ihr nicht länger ein einfacher Bettler, sondern ein Knappe im Dienste des Maximillian von Nordhain. Macht Euch bereit für unseren ersten Ausflug, mein treuer Knappe, denn gemeinsam wollen wir uns kopfüber ins Abenteuer stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24704] = { id = 24704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bösen Drachen im Un'Goro Krater", description = "Dieser Krater ist voll von einer bösartigen Brut von Drachen. Habt Ihr sie gesehen? Sie streifen umher und tragen ihre gezackten Rücken und Echsengesichter überall im Krater zur Schau.\n\nLasst Euch nicht von ihnen in die Irre führen, Knappe, denn diese Drachen sind keine Diener der anmutigen Alexstrasza. Sie sind ganz offensichtlich bösartig und benötigen dringend der Zuwendung einer Heldenklinge.\n\nIch habe beschlossen, dass ich nicht weniger als 15 von ihnen erlegen werde. Als mein Knappe müsst Ihr mich begleiten. Sollten wir getrennt werden, könnt Ihr mich hier an den heißen Quellen wiederfinden.", sourceObjective = "Helft Maximillian von Nordhain 15 \"Drachen\" zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24705] = { id = 24705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorfbewohner sind zum Retten da", description = "Ich habe so das Gefühl, dass wir in diesem Krater mehr als Drachen vorfinden. Mein Paladininstinkt sagt mir, dass Dorfbewohner in der Nähe sind, die unsere Hilfe brauchen. Wenn jemand in Not ist, dürfen wir es nicht ignorieren.\n\nLasst uns sofort aufbrechen, Knappe {name}! Das Volk von Un'Goro braucht uns!", sourceObjective = "Rettet den Schützling am See, den Schützling auf den Klippen und den Schützling im Norden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24706] = { id = 24706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister der Heißen Quellen von Golakka", description = "Einen Moment der Ernsthaftigkeit, {name}. Wir haben eine wichtige Aufgabe vor uns. Die verräterischen Drachen, die dieses Tal heimsuchen, werden in ihren Missetaten nicht innehalten, bis wir deren widerwärtige Brutmutter zur Strecke gebracht haben. Bevor wir aber auch nur daran denken können, solch eine Tat zu vollbringen, müssen wir das Licht um Beistand bitten.\n\nIch habe das Licht sich in der Nähe manifestieren sehen und zwar in der Form von Geistern, die an den Ufern der Heißen Quellen von Golakka schweben. Kommt, ich muss mit ihnen sprechen und sie um Hilfe bitten.", sourceObjective = "Wartet in der Nähe, während Maximillian von Nordhain mit 2 dampfenden Furien spricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24707] = { id = 24707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ballade von Maximillian", description = "Der Augenblick auf den wir gewartet haben, ist nun da, Knappe {name}. Un'Goros Brutmutter wird zu meinen Füßen sterben. Der Ernst unserer Aufgabe liegt mir schwer auf dem Gemüt, aber mit der Macht des Lichts auf unserer Seite können wir nicht scheitern.\n\nSeid Ihr zur Abreise bereit?", sourceObjective = "Helft Maximillian von Nordhain die Königin der Teufelssaurier zu töten. Wenn Ihr von Maximillian getrennt werdet, sprecht mit ihm an den Heißen Quellen von Golakka im Un'Goro Krater.", sourceObjectiveStatus = "unverified-source-field" }
quests[24708] = { id = 24708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fossilienfinder 3000", description = "Eines der Dinge, die ich am Meisten am Graben hasse, ist die Tatsache, dass man die Hälfte der Zeit nur Dreck findet. Deshalb habe ich den Großteil meiner Zeit hier mit Tüfteln statt mit Graben verbracht.\n\nLasst mich Euch zeigen, was ich erfunden habe: Der Fossilienfinder 3000. Ich habe gerade die letzten Handgriffe daran gemacht. Wenn er richtig funktioniert, sollte er die größten Fossilien in der Umgebung finden. Ich weiß, toll, oder?\n\nProbiert es einmal und schaut, ob Ihr nicht ein paar lächerlich große Dinosaurierknochen finden könnt.", sourceObjective = "Erhaltet eine gigantische Dinosaurierklaue", progress = "Habt Ihr etwas gefunden? Hat es funktioniert?", completion = "Was für einen interessanten Oberschenkelknochen Ihr mir da gebracht habt, aber warum ist er so scharf und geschwungen?\n\n...\n\nEinen Moment mal, das ist eine KLAUE? Ein Dinosaurier mit einer Klaue von solchen Ausmaßen wäre... nun ja, ziemlich groß gewesen, soviel ist sicher. Ist das das einzige Fossil, das Ihr dort gefunden habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24709] = { id = 24709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte von den zwei Schaufeln", description = "Einen Moment mal, dieser Knochen hat Spitzhackenkerben. Die stammen nicht von Euch, oder? Nein, ich erkenne diese Kerbe... das muss dieser verdammte Zwerg sein! Gah!\n\nErlaubt mir, dies kurz zu erklären. Es gibt noch einen anderen Archäologen südlich von hier, der Durrin Düsterschippe heißt. Er praktiziert eine rücksichtslose \"Nach mir die Sintflut\"-Archäologie, die sogar mich abstößt.\n\nEin unbezahlbares Fossil ruiniert durch schlampiges Graben. Das ist wirklich das Ende der Fahnenstange, Durrin!\n\n{name}, geht und bereitet Düsterschippe und seiner fahrlässigen Ausgrabung ein Ende.", sourceObjective = "Tötet Durrin Düsterschippe und erhaltet Durrins archäologische Erkenntnisse.", progress = "Ist es vollbracht? Habt Ihr seine Aufzeichnungen bergen können?", completion = "Ich wusste es! Durrin HAT hier herumgewühlt. Und er war dabei etwas auszugraben, was sich als der archäologische Fund des Jahrhunderts herausstellen könnte! Nun muss ich nur herausfinden, wo er die Knochen verstaut hat...\n\nDanke, {name}. Ihr wart mir eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nEr wird sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Welch sinnlose Verschwendung! Arthas ist zu weit gegangen! Ich hoffe nur, dass das, was wir in den Hallen der Reflexion vorfinden werden, all das wert ist.\n\nWenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Wir müssen weiter! Wir sind schon so weit gekommen... wir sind unserem Ziel ganz nah.\n\nIch muss Euch kurz verlassen und Elandra zum Luftschiff zurückschicken. Ich weiß nicht genau, wie wir fliehen sollen, wo wir so viele Leute verloren haben und nur noch wenige übrig sind, die unseren Pfad sichern.\n\nMacht weiter, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Lady Jaina Prachtmeer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid. Arthas ist zwar nicht hier, aber es wäre naiv, zu glauben, er ließe Frostgram vollkommen unbewacht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nDort wird er sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Die Hallen der Reflexion liegen vor uns. Wenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Macht weiter, wir sind dem Schwert ganz nahe.\n\nIch brauche einen Augenblick, um eine meiner Dunklen Waldläuferinnen zurück zum Luftschiff zu schicken. Jetzt, wo wir keine Unterstützung mehr haben, müssen Vorkehrungen getroffen werden. Wir brauchen jede Hilfe, die wir kriegen können!\n\nGeht, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid, {class}. Ich werde nicht so naiv sein, zu glauben, dass Arthas sein wertvolles Schwert vollkommen unbewacht zurückgelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24714] = { id = 24714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Kraters von Un'Goro heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie untersucht schon seit mehreren Monaten die örtliche Fauna am Fungusfels, aber sie hätte längst zurückkehren sollen. Ich befürchte das Schlimmste.\n\nKönnt Ihr mir helfen, sie zu finden?", sourceObjective = "Findet A-Me 01 am Fungusfels.", completion = "A-Me liegt bewegungslos vor Euch. Durch ihre Bauteile scheint kein Strom zu fließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24715] = { id = 24715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur von A-Me 01", description = "<Die Augen des Gorillaroboters leuchten plötzlich auf und er beginnt zu sprechen.>\n\n\"… Betriebskapazität… weniger als 5%... Ölbehälter… versehentlich beschädigt…\"\n\n\"… Kokosmilch benutzen… Fels… A-Me 01 retten…\"\n\n<A-Me 01 schließt die Augen.>", sourceObjective = "Ihr seid ziemlich sicher, dass A-Me 01 möchte, dass Ihr eine Kokosnuss von Un'Goro besorgt, sie am Felsen in der Nähe aufschlagt und ihr die Kokosmilch mit hoher Viskosität gebt.", progress = "<A-Me 01 ist in den Energiesparmodus gewechselt.>", completion = "Ihr schüttet die Kokosmilch in das, was Ihr für A-Mes Ölbehälter haltet. Ihr hört, wie die Zahnräder sich zu drehen beginnen und die Stellmotoren surrend anspringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24717] = { id = 24717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Affen von Un'Goro", description = "Hier in Un'Goro gibt es Unmengen von Gorillas, man muss nur wissen, wo man suchen muss!\n\nDoch während sie in Un'Goro ein gewohnter Anblick sind, gibt es im Norden deutlich weniger Affen. In der Ewigen Warte bringt ein Gorillapelz im Vergleich zum Marktwert hier unten den zehnfachen Preis!\n\nIch werde Euch nicht den ganzen Weg nach Winterquell schicken, das wäre unverantwortlich. Aber ich könnte Eure Hilfe bei der Beschaffung der Pelze brauchen.\n\nIm Nordosten, in der Nähe eines Wasserfalls, befindet sich der Fungusfels. Dort halten sich viele Gorillas auf. Vergesst nicht, auch in der Höhle nachzusehen!", sourceObjective = "Bringt Gremix am Mooshügel 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro.", progress = "Ich weiß nie, was gerade modern ist, also will ich ein paar verschiedene Farben. Versucht, Pelze von unterschiedlichen Gorillaarten zu sammeln.", completion = "Hui, gleich zwei von jeder Farbe! Ihr macht keine halben Sachen, was, {name}? Meine Kollegen und ich könnten jemanden wie Euch hier gut brauchen. Habt Ihr je daran gedacht, ins Profitgeschäft einzusteigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24718] = { id = 24718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige U'cha", description = "Als Ihr Euch umseht, bemerkt Ihr in diesem Teil der Höhle rote Fellfetzen. Von seiner Beschaffenheit her scheint es Gorillafell zu sein.\n\nIhr erinnert Euch an das Gespräch mit Gremix und seid Euch sicher, dass er an einem roten Gorillapelz sehr interessiert wäre, wenn Ihr einen bekommen könntet.", sourceObjective = "Bringt U'chas Pelz zu Gremix am Mooshügel.", progress = "Rotes Fell? Worauf wartet Ihr noch? Geht und schnappt Euch diesen roten Gorilla! Ich zahle Euch das Doppelte!", completion = "Schaut Euch das nur an! Nicht nur die Farbe, sondern auch die immense Größe… Damit könnte man locker einen Tauren ausstaffieren.\n\nBitteschön, {name}. Das habt Ihr Euch verdient. Bleibt in der Nähe. Ich bin mir sicher, dass wir noch andere Aufgaben für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24719] = { id = 24719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiße Klauen", description = "Halt, {race}. <Ein/Eine:c> {class} wie Ihr wäre mir gerade eine echte Hilfe.\n\nDirekt außerhalb dieses Lagers gibt es Raptoren mit tödlichen Klauen. Ich habe diese Klauen in einem druidischen Ritual benutzt, aber sie scheinen nicht zu funktionieren. Mir ist jedoch aufgefallen, dass die Klauen einiger Raptoren weiß sind, während die anderen meist tödliche schwarze Klauen haben.\n\nDie Erde geht manchmal komische Wege. Vielleicht könntet Ihr mir ein paar dieser weißen Klauen sammeln, damit ich es noch einmal probieren kann?", sourceObjective = "Sammelt 5 weiße Ravasaurusklauen.", progress = "Habt Ihr schon Klauen finden können?", completion = "Mein Mentor sagt, dass man der Natur manchmal etwas nehmen muss, bevor man ihr etwas zurückgeben kann. Diese Raptoren… Ich habe das Gefühl, dass sie für eine gute Sache gestorben sind.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24720] = { id = 24720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtkristalle", description = "Ich bin sicher, Ihr habt sie bemerkt, {name}. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?\n\nDie gelben Kristalle findet Ihr im Nordwesten, die roten im... Ach, Ihr werdet es schon herausfinden.", sourceObjective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün.", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, {name}!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24721] = { id = 24721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ostpylon", description = "Hoch auf den Klippen über mir gibt es einen großen Kristallpylonen. Ich weiß nicht, wer ihn dort aufgestellt hat, noch fällt mir ein Grund ein, warum man ihn an einem so merkwürdigen Ort errichten sollte.\n\nVielleicht könnt Ihr ja mehr herausfinden als ich. Mir persönlich ist es völlig egal, was dieses Ding tut, also braucht Ihr Euch nicht mehr bei mir zu melden. Aber vielleicht interessiert sich einer der Gelehrten in Marschalls Wehr ja für Eure Entdeckungen.", sourceObjective = "Berührt den Ostpylon im Krater von Un'Goro.", completion = "Es war klug von Euch, mir von diesem Pylonen zu erzählen, {name}. Genau damit beschäftigen sich meine Forschungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24722] = { id = 24722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordpylon", description = "Ihr habt uns schon so viele Gefallen getan, {name}… Jetzt lasst Gremix Euch einmal helfen. Die Angriffe auf Marschalls Zuflucht waren zweifelsohne schrecklich. Sie kamen ohne Vorwarnung und haben keine Gefangenen gemacht. Sie können von Glück sagen, dass so viele überlebt haben.\n\nVor ein paar Wochen bin ich auf den Klippen nordöstlich von hier, im Osten von Marschalls Zuflucht, an einem Kristallpylonen vorbeigekommen. Ich glaube, der Pylon und die Angriffe könnten irgendwie zusammenhängen. Könnt Ihr das vielleicht untersuchen? Ich bin mir sicher, dass jemand in Marschalls Wehr Euch dafür sehr dankbar sein wird.", sourceObjective = "Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro.", completion = "Und Ihr glaubt, das könnte irgendwie mit den Angriffen auf Marschalls Zuflucht zusammenhängen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24723] = { id = 24723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Westpylon", description = "Durrins Untersuchungen umfassen einen Punkt, der mich total fasziniert: eine mögliche Verbindung zwischen den Titanen und den Dinosauriern. J.D. Collie im Lager spricht immer von den Titanen hier, den Kristallen da… Vielleicht interessiert sie sich ja dafür.\n\nBevor Ihr Euch jedoch bei ihr meldet, solltet Ihr Euch den Kristallpylonen in der Nähe anschauen. Er befindet sich direkt oben auf den Klippen, westlich von hier. Er ist von Kristallen umgeben. Irgendwie hatte ich immer den Eindruck, dass er etwas mit den Titanen zu tun hat.", sourceObjective = "Findet den Standort des westlichen Kristallpylonen im Krater von Un'Goro.", completion = "Ein Pylon im Westen? Und eine Verbindung zwischen den Titanen und Dinosauriern? Das sind aber viele Informationen auf einmal, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24724] = { id = 24724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallflicker" }
quests[24725] = { id = 24725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsprengladung" }
quests[24726] = { id = 24726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkraft" }
quests[24727] = { id = 24727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallspitze" }
quests[24728] = { id = 24728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallbarriere" }
quests[24729] = { id = 24729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallschwächer" }
quests[24730] = { id = 24730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenklappern", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marschalls Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodonten und Dimetrodonten graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", sourceObjective = "Besorgt 8 Dinosaurierknochen.", progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodonten und Dimetrodonten stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich bin schon glücklich, wenn wir hier lebend rauskommen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[24731] = { id = 24731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Mahl", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nBeginnt Eure Suche im Westen.", sourceObjective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes.", progress = "Hört auf meine Worte, {name}. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, {name}. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24732] = { id = 24732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Fährte", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, {name}. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasauruseier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", sourceObjective = "Besorgt 2 Pheromondrüsen eines Ravasaurus.", progress = "Seid vorsichtig, {name}. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, {name}. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", sourceObjectiveStatus = "unverified-source-field" }
quests[24733] = { id = 24733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder für Lar'korwi", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Folgt dem Fluss weiter nach Norden und haltet nach einer Flussbiegung Ausschau. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit dieser Mischung ein.\n\nWenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", sourceObjective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro.", progress = "Lasst Euch nicht von Furcht überwältigen, {name}. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, {name}. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24734] = { id = 24734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren!", description = "Ihr müsst mir helfen, {name}! Mein Freund Ringo ist vor einer Weile aufgebrochen, um den Vulkan nördlich von hier zu erforschen, und er ist schon viel zu lange weg. Ich mache mir große Sorgen um ihn.\n\nMeint Ihr, Ihr könnt ihn suchen? Nehmt doch meine Feldflasche mit - wenn Ihr Ringo tatsächlich findet, dann hat er sie bestimmt nötig!", sourceObjective = "Sucht nach Hinweisen auf Ringo am Feuersäulengrat.", progress = "Ringos Sack liegt auf dem Felsen vor Euch.", completion = "Dies scheinen Ringos Habseligkeiten zu sein. Wenn er sie hier zurückgelassen hat, kann er nicht weit entfernt sein. Vielleicht solltet Ihr nach ihm suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24735] = { id = 24735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Hilfe von guten Freunden", description = "Argh... es ist so heiß...\n\nIch war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.\n\nBitte, bringt mich zu meiner Freundin Spraggel in Marschalls Wehr zurück. Ich glaube, es geht mir noch gut genug, um Euch dorthin zu folgen.\n\nAber ich fühle mich ziemlich schwach. Wenn ich also noch mal in Ohnmacht fallen sollte, dann bespritzt mich einfach mit etwas Wasser aus Spraggels Feldflasche. Das sollte helfen, hoffe ich...", sourceObjective = "Führt Ringo zu Spraggel Frock in Marschalls Wehr.\n\nFalls Ringo schwach werden sollte, gebt ihm eine Ohrfeige. Falls er ohnmächtig werden sollte, verwendet Spraggels Feldflasche, um ihn zu beleben.", completion = "Ringo ist in keiner besonders guten Verfassung, {name}, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24736] = { id = 24736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sappalots Flieger", description = "Ich baue einen Flugapparat!\n\nIch bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.\n\nAlso, werdet Ihr mir helfen? Ich muss nur noch die Flügel bauen und ich glaube, dass sich die Membranschuppen der Pterrordax und Dimetrodonten perfekt dafür eignen würden. Ich werde mich zwar garantiert nicht mit denen anlegen, aber Ihr seht ziemlich zäh aus. Wollt Ihr es nicht versuchen?", sourceObjective = "Sammelt 35 Membranschuppen eines Pterrordax'.", progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!", sourceObjectiveStatus = "unverified-source-field" }
quests[24737] = { id = 24737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superkleber", description = "Ich bin immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen, {name}. Wenn Ihr mir bei meiner neuesten Idee helft, dann gebe ich Euch ein bisschen was vom Gewinn ab. Na, was sagt Ihr dazu?\n\nDas hab ich mir gedacht!\n\nWir werden ein wenig Klebstoff herstellen. Geht zu den Teergruben nördlich von hier und beschafft mir etwas Teer. Aber nicht jeden x-beliebigen Teer, versteht Ihr? Ihr müsst den von den Kreaturen nehmen, die an den Teergruben leben. Und wenn Ihr meinen Teerkratzer an ihren Leichen verwendet, bleiben sogar Eure Patschehändchen schön sauber.", sourceObjective = "Sammelt 8 Proben superklebrigen Teers.", progress = "Und Tara hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist schon ganz schön klebrig. Ich meine, er ist klebrig, aber nicht \"Damit mache ich haufenweise Kohle\"-klebrig. Da muss ich wohl weitergrübeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[24740] = { id = 24740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulkanische Aktivität", description = "Willkommen. Ich bin Williden Marschall. Ich führe diese Expedition von Entdeckern und Wissenschaftlern zusammen mit meiner Schwester an. Habt Ihr einen Moment Zeit?\n\nIch mag diesen Anblick der Elementare auf diesem Vulkan da ganz und gar nicht, {class}. Wir haben zu viel Ausrüstung und zu viele Notizen... Wenn auch nur einer dieser wahnsinnigen Elementare sich in unser Lager verirrt, könnte er schlimme, schlimme Schäden anrichten.\n\nZeigt ihnen, dass sie sich nicht mit ihren neuen Nachbarn anlegen sollten. Und bringt mir die Asche, die sie zurücklassen... Wenn wir schon dabei sind, können wir uns gleichzeitig ein wenig der Wissenschaft widmen.", sourceObjective = "Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro.", progress = "Glaubt Ihr, dass der Vulkan in Un'Goro aktiv ist? Ich frage mich, warum er nicht explodiert ist, als der Kataklysmus uns getroffen hat.", completion = "Ich hoffe, das hat ihnen gezeigt, mit wem sie es zu tun haben. Ich nehme die Asche an mich… Irgendwann wird sie uns sicher nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24741] = { id = 24741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Tausch", description = "Hobart glaubt also, dass er uns mit diesem kleinen Gluckeneiern abspeisen kann? Pah! Wir besorgen uns richtige Eier!\n\nIch habe bereits ein paar Fallen auf dem Raptorenbuckel den Pfad entlang Richtung Osten aufgestellt. Die stacheligen Raptoren werden sich sofort auf die Gluckeneier stürzen, sodass Ihr sie gegen ihre größeren Eier tauschen könnt.\n\nGenial!", sourceObjective = "Sammelt 5 Eier eines stacheligen Raptors.", progress = "Wie viele habt Ihr zusammen? Ich kann das riesige Omelette fast schon schmecken, das wir daraus kochen werden!", completion = "Super! Schaut nur, wie groß diese Dinger sind!\n\nDie kann Wurfhammer sicher nicht überbieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24742] = { id = 24742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle finden", description = "Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!\n\nHeiße Stellen erkennt Ihr in der Regel an einer leuchtenden Felssäule. Ihr findet sie um den Feuersäulengrat herum. Eine Umrundung sollte eigentlich schon genügen.", sourceObjective = "Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, benutzt das Thermometer, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", progress = "Ich würde ja selbst gehen, aber... ich habe ein wenig Angst vor den Feuerelementaren dort!", completion = "Diese Ergebnisse sind verblüffend! Mein Chef wird sehr zufrieden sein. Vielen Dank, lieber {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschneide", sourceObjective = "Hört gut zu, {class}. Indem Ihr diese Waffe annehmt, wird Euer Schicksal besiegelt.\n\nSiegt oder geht unter.\n\nIch habe Euch auf diesen Weg gebracht, womit ich die Verantwortung für Euch übernommen habe. Solltet Ihr ins Wanken geraten, ist es meine Pflicht, Euch von diesem Leben zu erlösen.\n\nDenkt an meine Worte, {race}, und versagt nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[24744] = { id = 24744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das größte Ei aller Zeiten", description = "Bäm Megabombe? Was glaubt er eigentlich, wer er ist? Seine Eier von stacheligen Raptoren sind gar nichts gegen das, was wir uns jetzt besorgen werden!\n\nWie Ihr wisst, verfügt die Instastadt für genau solche Nahrungsengpässe über ein Mikromechahuhn. Und zu unserem großen Glück konnte ich mit meinem überragenden Intellekt ermitteln, wohin unser wunderbares vorprogrammiertes Geflügel entschwunden ist.\n\nGeht nach Norden zur Versengten Rinne. Aber Vorsicht! Seine Platinen sind durchgebrannt und ich glaube, es ist gar nicht mehr so mikro!", sourceObjective = "Besorgt Euch das größte Ei aller Zeiten.", progress = "Malt Euch nur die Lobeshymnen aus, die auf mich herniederregnen werden… äh… ich meine uns, wenn wir ihnen das größte Ei aller Zeiten bringen!", completion = "Heureka! Und wieder einmal hat mein Genie den Tag gerettet! Nehmt das, Bäm Megabombe!\n\nUnd jetzt wollen wir den Erfolg ernten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Inspektor Snip Schnappbolz in Sturmwind.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr denn da?\n\nUi, das ist groß! Riesig! So viele verrückte Details auf einem Haufen! Danke, Ihr habt uns wirklich sehr geholfen. Mit Euch kann man wirklich gut zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24747] = { id = 24747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage!", description = "Diese zwergischen Artilleriegranaten haben einen eingebauten Luftdetonationszeitzünder. Das ist ja einfach! Ihr müsst nur eine der Artilleriegranaten in der Ladebucht sabotieren und sie dann hinauf ins Lager befördern. Bumm, Baby. BUMM!!\n\nIhr findet die Granaten in einer der beiden Ladebuchten hinter der Hauptwerkstatt auf dieser Ebene. Sie befindet sich direkt um die Ecke.\n\nSobald Ihr die Artilleriegranate manipuliert habt... Rennt! Rennt wie der Wind, {name}! Dann meldet Euch bei Gann im Lager zurück. Ich bin direkt hinter Euch.", sourceObjective = "Sabotiert eine zwergische Artilleriegranate und flüchtet dann aus Bael'dun bevor es explodiert.", completion = "Bael'dun? Zerstört?\n\n<Gann dreht seinen Kopf, um hinter sich zu spähen, wo dunkle Rauchwolken den Himmel verdunkeln, und zuckt schmerzerfüllt zusammen.>\n\n{name}, mein Freund. Ihr habt Taurajo und das Volk der {race} gerächt. Die Eindringlinge werden sich von dem Schlag nicht so schnell erholen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht des Lichkönigs", description = "Schattengram; eine neu geschmiedete Waffe, die bereits mit der Geschichte dieser Welt getränkt ist, wiedergeboren in eine beispiellose Bestimmung.\n\nMit dieser Waffe tragt Ihr eine feierliche Verantwortung, und die Zeit, dieser Verpflichtung nachzukommen, ist gekommen.\n\nNehmt diese mythische, legendäre Waffe und marschiert gegen den Feind. Rächt die zahllosen Helden, die in diesem gnadenlosen Krieg ihr Leben ließen. Bringt ihren geschundenen Seelen Frieden.\n\nStählt Euch, {class}, und führt Schattengram, um den Sinn ihrer Erschaffung zu erfüllen.", sourceObjective = "Hochlord Darion Mograine in der Eiskronenzitadelle will, dass Ihr den Lichkönig tötet.", completion = "Dann ist es also endlich vollbracht.\n\nMögen die Völker Azeroths unserer Taten hier ewig gedenken. Mögen die Opfer so vieler für immer in ihren Herzen brennen. Mögen sie im Angesicht großer Bedrohungen nie die Bereitschaft verlieren, ihr Leben für andere zu riskieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit unheiliger Macht", description = "Bevor Eure Waffe ihre volle Kraft entfalten kann, muss sie mit den für sie charakteristischen Kräften ausgestattet werden. Die erste davon ist Unheiligkeit.\n\nIhr müsst jemanden namens Professor Seuchenmord ausfindig machen und töten, doch das ist noch nicht alles. Ihr müsst seine eigenen Mittel und Methoden gegen ihn verwenden.\n\nFindet einen Weg, seinen mutierten Schleim zu absorbieren. Benutzt die stinkende Substanz, um Eure Waffe mit unheiliger Macht zu erfüllen. Erst dann sollt Ihr Eure nächste Aufgabe von mir erhalten.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit unheiliger Macht erfüllt und Professor Seuchenmord tötet.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Gut gemacht, {class}!\n\nWir kommen dem Abschluss unserer Arbeit immer näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[24750] = { id = 24750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Soratha im Osten.", sourceObjective = "Trefft Soratha auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Entschlossenheit. Feurige Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24751] = { id = 24751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der arkanen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24752] = { id = 24752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Magiers", description = "Wenn Ihr Eure Stärke weiterentwickelt, werdet Ihr Euch neue Zauber überlegen und neue Wege, um Eure arkanen Talente anzuwenden.\n\nGeht nun, steigert Eure Fähigkeiten und kommt dann zurück und zeigt mir, was Ihr drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Frostnova zu erlernen. Wendet es zweimal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24753] = { id = 24753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24754] = { id = 24754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24755] = { id = 24755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Blutes", description = "Nun kann Eure Waffe mit der Macht des Blutes versehen werden.\n\nIhr müsst gegen Blutkönigin Lana'thel kämpfen und Euch ihrem Blutspiegel aussetzen. Durch diese Macht wird Schattenschneide das Blut des nächstgelegenen Lebewesens trinken. Das wäret dann Ihr, {race}.\n\nLasst, sobald die Klinge erwacht ist, den rasenden Blutdurst der Königin über Euch kommen, gebt Euch ihm hin und bereitet ihr einen schmachvollen Tod.\n\nMögen ihre Schreie in den Ohren des Lichkönigs schmerzen, während er auf sein Schicksal wartet!", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit der Macht des Blutes erfüllt und Blutkönigin Lana'thel besiegt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Gut gemacht, {class}.\n\nSchattengram ist fast in Reichweite.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Frostes", description = "Nun ist Schattenschneide bereit, mit der letzten Macht erfüllt werden.\n\nSindragosa, das persönliche Reittier des Feindes, muss fallen! Doch bevor Ihr sie tötet, müsst Ihr ihrer Frostatemattacke viermal widerstehen, ohne zu sterben.\n\nIst der Drache erst einmal beseitigt, steht nichts mehr zwischen Euch und dem Lichkönig.", sourceObjective = "Hochlord Darion Mograine hat Euch den Auftrag erteilt, Sindragosa zu töten, nachdem Ihr 4-mal ihren Atemattacken ausgesetzt wart, während Ihr Schattenschneide führt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Die Axt hat die Mächte aufgesogen, {race}, und die Schmiede ist bald bereit für die Erschaffung von Schattengram...", sourceObjectiveStatus = "unverified-source-field" }
quests[24758] = { id = 24758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Nekali im Osten.", sourceObjective = "Trefft Nekali auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDafür seht Ihr aber ganz schön erfahren aus. Weise Augen. Vielleicht wird aus Euch noch ein echter {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24759] = { id = 24759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der natürlichen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24760] = { id = 24760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Schamanen", description = "Wenn Ihr stärker werdet, fangt Ihr an die Stimmen Eurer Vorfahren zu hören, die Euch ihre Geheimnisse beibringen.\n\nDas erste davon ist, die Macht der Elemente in Eure Waffe zu leiten. Dann könnt Ihr einen schnellen, brutalen Angriff auf Eure Gegner ausführen. Das sollte Euch leichtfallen und für Euch von großem Nutzen sein.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Urtümlicher Schlag zu erlernen. Wendet diesen dann 3-mal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24761] = { id = 24761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24762] = { id = 24762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24763] = { id = 24763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24764] = { id = 24764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Zen'Tabra im Osten.", sourceObjective = "Trefft Zen'Tabra auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Wildheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24765] = { id = 24765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der druidischen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", progress = "Kraft ist nicht alles, um einen Gegner zu besiegen, und ganz sicher ist sie nicht alles, um am Leben zu bleiben. Beim Kampf kommt es auf die Balance an. Alles hat seine Zeit und seinen Ort.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24766] = { id = 24766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Druiden", description = "Wenn Ihr stärker werdet, wird Eure Fähigkeit, die Kräfte der Natur anzurufen, auch besser. Wollt Ihr's sehen?\n\nSammelt mehr Erfahrungen und zeigt mir, was Ihr gelernt habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Mondfeuer zu erlernen. Probiert es an einem Tikiziel auf dem Übungsgelände der Dunkelspeere aus.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24767] = { id = 24767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24768] = { id = 24768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24769] = { id = 24769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24770] = { id = 24770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Legati im Osten.", sourceObjective = "Trefft Legati auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Gerissenheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24771] = { id = 24771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffen zu schwingen habt, mit denen Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24772] = { id = 24772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Schurken", description = "Wenn Ihr mit Gegnern kämpft, lernt Ihr neue Tricks, mit denen Ihr noch besser werdet.\n\nEinen solltet Ihr schon bald lernen, damit Ihr ihre Schwächen aufdecken und vernichtende Comboangriffe ausführen könnt. Nachdem Ihr ein paar Schläge zur Schwächung Eurer Gegner ausgeführt habt, erledigt sie mit einem brutalen Ausweiden-Angriff.\n\nWenn Ihr es gelernt habt, probiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Ausweiden zu erlernen. Wendet es dann 3-mal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24773] = { id = 24773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24774] = { id = 24774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24775] = { id = 24775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24776] = { id = 24776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Ortezza im Osten.", sourceObjective = "Trefft Ortezza auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Wildheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24777] = { id = 24777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Angriffen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24778] = { id = 24778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Jägers", description = "Wenn Ihr den Bogen raushabt, findet Ihr heraus, wie man neue Tricks macht.\n\nZuerst müsst Ihr lernen, zwischen Schüssen eine ruhige Hand zu behalten, sonst seid Ihr schnell erschöpft und richtet keinen wirklichen Schaden mehr an.\n\nLos, sammelt noch mehr Erfahrungen, bis Ihr es rausgefunden habt, und kommt dann wieder. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Zuverlässiger Schuss zu erlernen. Wendet den zuverlässigen Schuss 5-mal bei einem Tikiziel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24779] = { id = 24779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24780] = { id = 24780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24781] = { id = 24781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[24782] = { id = 24782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Tunari im Osten.", sourceObjective = "Trefft Tunari auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDafür seht Ihr aber sehr ausgeglichen aus. Ruhige Augen. Vielleicht wird aus Euch noch eine echte {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24783] = { id = 24783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der heiligen Künste versteht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24784] = { id = 24784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Wenn Ihr da draußen in der Welt mehr Fähigkeiten bekommt, werdet Ihr neue Kräfte entdecken.\n\nProbiert es aus und versucht, stärker zu werden. Kommt dann wieder, wenn Ihr etwas Neues gelernt habt. Ihr könnt mir dann zeigen, was Ihr drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Wendet es 5-mal bei Tiki-Trainingsattrappen an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24785] = { id = 24785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24786] = { id = 24786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", progress = "Jeder Troll muss sich beweisen, bevor er das Trainingsgelände verlassen darf.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24787] = { id = 24787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24788] = { id = 24788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger heroischer Dungeon (Erster)" }
