quests[24896] = { id = 24896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, klassischer Dungeon 65-70 (Nter)" }
quests[24897] = { id = 24897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Stadt", description = "Wir lagen falsch. Es waren nicht die Naga, die sich auf einen Angriff vorbereiteten… Es war der benachbarte Stamm der Oomlot!\n\n{name}, Ihr müsst zurück nach Instastadt. Die Pygmäen greifen bereits an!\n\nHier, nehmt dies hier. Wir haben ihn von einem Pygmäen gekauft, der sagte, er gehörte einst einem großen Anführer ihres Volkes. Jemandem namens \"Großer dunkler Helm\".\n\nEr sollte sie gut genug täuschen, damit sie Euch nicht angreifen.", sourceObjective = "Sprecht mit Sassy Hartzang in Instastadt auf den Verlorenen Inseln.", completion = "{name}? Wir sind gerettet!\n\nWem mache ich was vor. Wir werden alle sterben!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24901] = { id = 24901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instastadt: Unter Angriff", description = "{name}, Ihr müsst uns beschützen!\n\nIch habe bereits veranlasst, dass diese Eierköpfe die Stadt mit den Kanonen verteidigen, aber es scheint unendlich viele von diesen Oomlotkriegern zu geben!\n\nSchwingt Euch hinter einen der B.C. Eliminatoren und vernichtet die Pygmäen, die unsere Stadt bedrohen!", sourceObjective = "Verwendet einen B.C. Eliminator, um 30 Krieger von Oomlot zu töten.", progress = "Das reicht noch nicht, Schätzchen. Könnt Ihr nicht ein paar mehr erledigen?", completion = "Gut, das sollte fürs Erste reichen, aber sie haben einige Stadtbewohner gefangen genommen.\n\nWir müssen auf ihrem Grund und Boden gegen sie kämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24902] = { id = 24902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd nach Sylvanas", description = "Dann ist es also wahr? Gilneas hat seinen liebsten Sohn verloren.\n\nWir werden trauern, sobald all dies vorbei ist, aber keinen Tag früher.\n\nWir gönnen uns den Luxus der Trauer nicht, solange der Feind noch gilnearische Luft atmet.\n\nDie Männer meines Vaters sind bereit, zuzuschlagen, solange wir die Fährte der Bansheekönigin noch verfolgen können. Sagt einfach Bescheid, wenn Ihr bereit seid. Liam muss so schnell wie möglich gerächt werden.", sourceObjective = "Folgt Tobias Dunstmantel auf der Jagd nach Sylvanas.", progress = "Habt Ihr sie gefunden, {name}?", completion = "Die Seuche? Etwas so Hinterhältiges, dass nicht einmal die Orcs mit ihrem Einsatz einverstanden sind? Wir müssen König Graumähne davon berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24903] = { id = 24903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache oder Überleben", description = "Sagt Graumähne Bescheid, dass wir Sylvanas unsere Fährtenleser hinterhergeschickt haben und berichtet ihm von der Seuche.\n\nNun muss er entscheiden: Starten wir einen großangelegten Angriff auf die Verlassenen oder versuchen wir, unsere Überlebenden zu evakuieren?", sourceObjective = "Sprecht mit König Genn Graumähne auf dem Graumähnenhof in Gilneas.", completion = "Ihr stellt mich vor die schwierigste Entscheidung meines Lebens, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24904] = { id = 24904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Gilneas", description = "Die Zeit ist gekommen, {name}. Wir haben jeden einzelnen Gilneer zusammengetrommelt und ihm eine Waffe in die Hand gedrückt.\n\nEs ist Zeit, dass wir uns dem Feind direkt stellen. Zeit, Sylvanas und ihren verlassenen Hunden ein für alle Mal eine Lektion zu erteilen.\n\nLiam führt den Angriff von diesem Tor aus an. König Graumähne und mein Vater überwachen die Angriffe in den anderen Vierteln.\n\nAuch Ihr spielt bei der Sache eine wichtige Rolle. Nehmt dieses Rapier. Verwendet es, um unsere Männer und Frauen in der Schlacht anzufeuern. Sprecht mit Krennan Aranas, um an der Schlacht um Gilneas teilzunehmen.", sourceObjective = "Erringt den Sieg in der Schlacht um Gilneas", completion = "Wir haben die Verlassenen zurückgedrängt. Wir haben die Kontrolle über drei der vier Viertel.\n\nAber zu welchem Preis…", sourceObjectiveStatus = "unverified-source-field" }
quests[24905] = { id = 24905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich für einen Gefallen revanchieren", description = "Wisst Ihr, als Ihr eben unterwegs wart, kam Megs vorbei. Ich hab sie schon seit Monaten nicht mehr gesehen, aber sie hat sich nicht wirklich für mich interessiert und wollte mir nur sagen, dass sie mehr Arbeit übrig hat.\n\nSie sagte, sie würde sich im Truppenlager der Dünenbrecher niederlassen wollen, und irgendwas mit Ogern. Da Ihr hier ja jetzt fertig seid, könnt Ihr ja mal schauen, ob Ihr ihr helfen könnt. Einen Goblin wie sie würde ich nicht warten lassen.", sourceObjective = "Findet Megs Schredderschreck beim Truppenlager der Dünenbrecher.", completion = "Diesmal habe ich etwas Tolles für Euch, {name}. Wir werden diese Oger in die Horde einführen... und unter uns arbeiten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24906] = { id = 24906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung an der Küste", description = "Wir müssen die Waren auf diesem Markt so schnell wie MÖGLICH in den Umlauf bringen, wenn wir wettbewerbsfähig sein wollen. Ich habe schon einen Einstiegspunkt gefunden.\n\nGadgetzan ist von Piraten eingenommen worden, aber viele der Güter, die von den Schiffen geworfen wurden, sind noch intakt. Sie wurden nur weggespült. Viele davon werden südlich der Stadt angespült.\n\nGeht dorthin und beginnt, zu sammeln, was noch verwertbar ist. Da unten schwimmt der Profit sprichwörtlich kistenweise herum.", sourceObjective = "Sammelt 7 Dampfdruckvorräte.", progress = "Mal sehen, was Ihr so gefunden habt.", completion = "Hmm, vieles ist verwendbar. Gutes Zeug habt Ihr gefunden. Ich hab natürlich auch schon Käufer, die Schlange stehen.\n\nHier habt Ihr einen Vorschuss für die restliche Arbeit, die Ihr noch für mich und das Bilgewasserkartell verrichten werdet... Partner!", sourceObjectiveStatus = "unverified-source-field" }
quests[24907] = { id = 24907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfützenstampfer", description = "Also, unsere Lage ist wie folgt: wenn wir die Präsenz des Bilgewasserkartells in Gadgetzan fördern möchten, müssen wir anfangen, den Bewohnern Dienstleistungen anzubieten.\n\nDie neue Küste ist ideal für das Geschäftsleben, aber das Meer hat auch einige Ungeheuer mitgebracht. Sie sind groß, übel und machen den Immobilienmarkt kaputt.\n\nGeht zu den seichten Wassern südlich der Stadt und tötet so viele, wie Ihr könnt. Ihr bekommt natürlich eine Gewinnbeteiligungn an den Geschäften, die ich in der Zwischenzeit abschließe.", sourceObjective = "Tötet 8 Gezeitenschreiter.", completion = "Die Immobilienpreise steigen, seit Ihr weggegangen seid. Die Aussicht aufs Meer ohne salzige, knorrige Riesen, die durch die Pfützen stampfen gefällt den meisten einfach besser.\n\nHier ist Euer Anteil, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24910] = { id = 24910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenrettung", description = "Nun gut, {name}. Wir haben uns mit Kleinkram über Wasser gehalten, aber jetzt ist es an der Zeit, richtig loszulegen.\n\nBei den Ruinen von Dampfdruckpier sind immer noch hilflose Goblins, die auf Rettung warten. Jeder einzelne von ihnen ist ein potentieller Kunde. Sie schießen auf alle Boote, die den Hafen verlassen - also schlage ich vor, wir fliegen!\n\nAußerhalb der Stadt, in der Nähe der Docks ist ein Heißluftballon, den wir nehmen können. Geht schon mal vor, ich komme dann nach.", sourceObjective = "Bringt Lebensraketen zu 5 Überlebenden des Dampfdruckkartells und benutzt Bomben, um 40 Blockierer der Südmeerfreibeuter zu töten.", completion = "Ist es nicht toll, wenn man etwas Nettes macht und dabei auch noch enorme Finanzspritzen für die Zukunft sichern kann? Da wärmt es mir vor Freude mein kleines Goblinherz.\n\nIhr habt tolle Arbeit geleistet. Bald wird Gadgetzan uns gehören. Hier ist ein kleines Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[24911] = { id = 24911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das tropische Paradies ruft", description = "He, Ihr scheint mir ein anspruchsvoller Abenteurer zu sein. Seid Ihr auf der Suche nach etwas ganz Neuem? Etwas Exotischem? Etwas… Profitträchtigem?\n\nNun, dann schüttelt den Sand aus Euren Schuhen, denn ich habe ein Angebot für Euch. Williden Marschall ist auf der Suche nach fähigen Söldnern wie Euch. Er hat sein Lager in Marschalls Wehr direkt südöstlich des Vulkans inmitten des blühenden Kraters von Un'Goro errichtet.\n\nAber bedenkt, dass nicht jeder für das Paradies geschaffen ist, {race}. Es liegt an Euch. Eure tropische Oase wartet!", sourceObjective = "Meldet Euch bei Williden Marschall in Marschalls Wehr im Krater von Un'Goro.", completion = "He, Hol'anyee, schau dir mal die Aufmachung von dem hier an!\n\n<Williden dreht sich zu Euch.>\n\nÄhem. Unser Rekrutierer schickt Euch? Gut. Fangen wir mal mit der Wahrheit an: Un'Goro ist nicht das perfekte Elysium, das Euch wahrscheinlich versprochen wurde. Aber das habt Ihr sicher auf dem Weg hierher schon bemerkt.\n\nWollen wir an die Arbeit gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24912] = { id = 24912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Macht erfüllen", progress = "<Hochlord Darion Mograine spricht Euch zielstrebig an.>\n\nSchattenschneide ist bereit, ihre letzte Gabe der Macht zu erhalten.\n\nDie Zeit ist gekommen, das Schmieden von Schattengram zu wagen!", completion = "Tretet zur Seite, {class}, und wappnet Euch." }
quests[24913] = { id = 24913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkt des Lichtes", description = "Magtoor wird von Sekunde zu Sekunde schwächer, {name}. Meine Arznei ist vorbereitet... sie muss einfach funktionieren. Sie muss!\n\nIhr habt so viel für uns beide getan. Es wäre mir eine Ehre, wenn Ihr in diesen Momenten bei Magtoor bleiben könntet - vielleicht sind es seine letzten.", sourceObjective = "Helft Anchorit Avuun, sich von Magtoor zu verabschieden.", completion = "Ich bin tiefbewegt, {name}. Prophet Velen befand sich in streng bewachter Abgeschiedenheit. Er wagte es nicht, seine Energie auf irgendetwas anderes als die letzte Konfrontation zu verschwenden, die er vorhersagte.\n\nUnd doch ist er höchstpersönlich hergekommen, um eine sterbende Seele zu trösten.\n\nIch muss auch Euch danken, für die Hilfe bei meinem letzten Versuch, meinem Freund Trost zu geben. Meine Forschungen werden weitergehen... und ich hoffe, dass Magtoor mich weiterhin dabei behütet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24914] = { id = 24914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persönliches Eigentum", description = "Ihr könnt auf dieser Truhe keine Scharniere oder Öffnungen finden. Würde man das Poltern von Gegenständen in ihrem Inneren nicht hören, könnte man leicht meinen, dass sie aus massivem Metall bestünde.\n\nWenn irgendjemand wissen sollte, wie man sie öffnet, dann wird das Hochlord Mograine sein.", sourceObjective = "Bringt die versiegelte Truhe zu Hochlord Darion Mograine in die Eiskronenzitadelle.\n\nBereitgestellter Gegenstand:", completion = "<Nachdem er die komplexen Runenmuster auf jeder Seite der Truhe mit den Fingern nachverfolgt hat, erscheinen die Umrisse eines Deckels und ein Klicken schallt durch die Halle.>\n\nBitte sehr, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24915] = { id = 24915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenkunft mit Mograine", progress = "Was haltet Ihr da in Händen, {class}?\n\nEs ruft nach mir und weckt Gefühle in mir, von denen ich dachte, dass sie schon lange gestorben seien.", completion = "Unmöglich...\n\nVater, bist du das?!\n\nIhr habt mir einen großen Dienst erwiesen, Held. Dafür gebe ich Euch das Zaumzeug meines treuen Rosses. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen." }
quests[24916] = { id = 24916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jainas Medaillon", progress = "Ja, {class}? Wie kann ich behilflich sein?", completion = "Was... wie habt Ihr es geschafft, in seinen Besitz zu kommen!?\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich könnte es nicht übers Herz bringen, dieses Medaillon zu behalten, aber ich werde eine Verzauberung darauf legen, die Euch von Nutzen sein könnte. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen." }
quests[24917] = { id = 24917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muradins Klagelied", progress = "Was hast du da, {race}?", completion = "Jawohl. Ich kenne diese Klinge... und ich werde mich bis ans Ende meiner Tage an sie erinnern - an jenen Zeitpunkt, der für immer verloren sein wird.\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich möchte Euch etwas von den Frosterben zum Geschenk machen. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen." }
quests[24918] = { id = 24918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanas' Rache", progress = "Was ist, {race}?", completion = "<Sylvanas ist einen Moment lang in Gedanken versunken. Schließlich richtet sie ihren Blick auf Euch.>\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich gebe Euch den Segen der Bansheekönigin. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen." }
quests[24919] = { id = 24919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung des Lichtbringers", progress = "Wie kann ich behilflich sein, {race}?", completion = "<Uther starrt einen Moment lang sprachlos auf die Medaille.>\n\nArthas' Medaille.\n\nIch kann mich gut an den Tag erinnern, als ich sie ihm überreichte...\n\nIhr habt mir einen großen Dienst erwiesen, Held. Nun kann meine Seele in Frieden ruhen. Hier, ich biete Euch etwas, das im Laufe der Zeit vergessen wurde - eine Erinnerung. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen." }
quests[24920] = { id = 24920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unvermeidliche verlangsamen", description = "So gerne ich schnelle und brutale Rache üben würde… muss ich erst die Erinnerung an meinen Sohn ehren. Für ihn stand das Wohl seines Volkes immer an erster Stelle.\n\nDer Totengräberpass verläuft unterirdisch unter dem Nordtorfluss hindurch. Ihr müsst verhindern, dass die Seuche sich ausbreitet, wenn wir unsere Männer, Frauen und Kinder zu Aderics Ruhestätte evakuieren.\n\nWir haben eine der gefürchteten Bombenfledermäuse der Verlassenen gefangen. Ich möchte, dass Ihr diese Höllenbestie so gut wie möglich fliegt und denen, die die Seuche zu unserem Volk bringen wollen, die Hölle heiß macht. Beeilt Euch!", sourceObjective = "Benutzt die gefangene Reitfledermaus, um 6 Katapulte der Verlassenen und 40 einfallende Verlassene zu vernichten.", progress = "Habt Ihr es erledigt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Fast alle sind heil auf die andere Seite gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24921] = { id = 24921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung für Aubrey", description = "Ihr da! Seid Ihr gerade mit dem Schiff angekommen? Willkommen in Kalimdor, einem Land, das sich alle Mühe geben wird, Euch zu töten oder bei dem Versuch zu sterben.\n\nIn der Burg gibt es Ärger - aber ich bin sicher, das habt Ihr auf Euren Weg hinein bereits bemerkt. Admiral Aubrey braucht alle Mann an Deck, wenn wir das hier überstehen wollen. Betrachtet Euch als eingezogen, {class}!\n\nFolgt der Straße den Hügel hinauf und Ihr findet Aubrey oben auf dem Turm.", sourceObjective = "Meldet Euch bei Admiral Aubrey in der Feste Nordwacht.", completion = "Hm? Bei welcher Einheit seid Ihr, {class}?\n\nEgal, wir brauchen jeden Mann. Meine Flotte ist zerschlagen und sie sind in die Feste eingebrochen. Seid Ihr bewaffnet? Das reicht mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[24922] = { id = 24922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, klassischer, heroischer Dungeon (Erster)" }
quests[24923] = { id = 24923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufälliger, heroischer Burning Crusade-Dungeon (Nter)" }
quests[24924] = { id = 24924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot", description = "Die Pygmäen haben die meisten unserer Leute in ihr Dorf verschleppt. Wer weiß, was für böse Dinge sie im Schilde führen?\n\n{name}, Ihr müsst dorthin gehen und die Gefangenen befreien, bevor die Pygmäen ihre Voodoozauber auf sie wirken können!\n\nIzzy befindet sich bereits in der Nähe von Oomlot im Südosten. Sie kann Euch sagen, was dort vor sich geht.\n\nEuer Pygmäenhelm scheint ganz schön mitgenommen zu sein, aber er sollte lange genug halten, damit Ihr heil dort ankommt.\n\nHoffe ich zumindest.", sourceObjective = "Sprecht mit Izzy bei Oomlot auf den Verlorenen Inseln.", completion = "{name}? Was macht Ihr denn hier? Und warum habt Ihr diesen komischen Pygmäenhelm auf? Der fällt ja gleich auseinander!\n\nIch bin froh, dass man Euch hierher geschickt hat. Ich hatte schon befürchtet, dass sie diesen Deppen Wurfhammer und seine speichelleckende Assistentin schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24925] = { id = 24925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit die Gefangenen", description = "Sie halten ein paar unserer Leute dort gefangen. Ich weiß, dass sie merkwürdige Rituale mit ihnen durchführen. Es scheint fast, als würden sie ihnen die Lebenskraft aussaugen!\n\nIhr müsst in das Dorf gehen und die Gefangenen befreien, bevor es zu spät ist!", sourceObjective = "Befreit 5 gefangene Goblins.", completion = "Tolle Arbeit! Aber das ist nicht einmal die Hälfte der Gefangenen, die sie aus der Stadt entführt haben.\n\nVerflixt! Sie müssen die restlichen Gefangenen zu ihren anderen Dörfern oben im Vulkan gebracht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[24926] = { id = 24926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst für A-Me 01", description = "Grüße. Ich Einheit A-Me 01. Ihr… {race}?\n\nA-Mes Mission zur Untersuchung der einheimischen Gorillas erfolgreich. A-Me Daten gesammelt, die Karna brauchen.\n\nA-Me 01 aber noch nicht zurückkehren. A-Me hat jetzt neue Familie. A-Me hier bei Gorillas bleiben.\n\n<A-Me 01 nimmt ein kleines Gerät von ihrer Hand ab und gibt es Euch.>\n\nIhr Daten zurückbringen zu Karna. Ihr ihr sagen, was passiert sein.", sourceObjective = "Bringt A-Me 01s Fingerfestplatte zurück zu Karna Wirrbart am Mooshügel im Krater von Un'Goro.", progress = "W… was ist das?", completion = "Sie hat sich entschlossen, zu bleiben? Faszinierend… Ich muss mir diese Daten ansehen und herausfinden, warum.\n\nNochmals danke, {name}. Ich weiß Eure Hilfe wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24927] = { id = 24927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des toten Mannes", description = "Seht, Schätzchen, Ihr solltet eigentlich sehen können, was hier los ist. Auf der einen Seite sind die Seeräuber, auf der anderen die Goblins, und die Goblins bekämpfen die Piraten. Ein paar arme, kleine Gnome versuchen es auch.\n\nIch werde es euch noch einfacher machen: wir müssen viele Piraten töten. Macht das, ja? Wir wollen ja nicht, dass die Gnome mehr erwischen als wir.", sourceObjective = "Tötet 15 Seeräuber der Südmeerfreibeuter jeglicher Art.", completion = "Ich freue mich, mitteilen zu können, dass unser Markenbewusstsein in dieser Gegend enorm gestiegen ist, seid Ihr die meisten getötet habt, die uns nicht hier haben wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24928] = { id = 24928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niederbrennen!", description = "Ich habe eine gründliche Untersuchung des Immobilienmarkts angestellt und leider sind die Marktwerte hier viel zu niedrig, um für uns nützlich zu sein. Wir werden renovieren müssen.\n\nZum Glück für Euch weiß ich ein paar Sachen über Brandstiftung. Ich hoffe, Ihr auch! Ihr werdet diese unglaublich sicheren Flaschen mit hochentzündlichem Rum auf die heruntergerannten, schmutzigen Hütten dort drüben werfen.\n\nVersucht, in der entgegengesetzten Windrichtung zu stehen.", sourceObjective = "Brennt die nordwestliche Hütte, die südöstliche Hütte und die nordöstliche Hütte nieder.", completion = "Wunderbare Arbeit. Habt Ihr schon einmal mit dem Gedanken gespielt, mit der Brandstiftung Euren Lebensunterhalt zu verdienen? Ich kenne in der Branche ein paar Leute, da geht schon einiges.\n\nNa gut, darüber können wir uns später unterhalten. Es gibt noch mehr zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[24929] = { id = 24929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlasst eine Botschaft", description = "Der Anführer der Oomlot, Yngwie, ist zu mächtig, als dass wir ihn am Leben lassen könnten. Er brüllt Unsinn vom erhöhten Westteil des Dorfes herab, jenseits der Seilbrücke.\n\nGeht zu ihm und tötet ihn, bevor er den Rest des Dorfes auf uns hetzt.\n\nEin Kinderspiel!", sourceObjective = "Tötet Yngwie.", completion = "Gute Arbeit, Kumpel! Ich hoffe, er war kein allzu harter Brocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24930] = { id = 24930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr schon dabei seid", description = "Wenn König Graumähne möchte, dass Ihr Euer Leben riskiert, um einen bekannten Verräter zu retten, soll mir das Recht sein.\n\nKönntet Ihr mir einen Gefallen tun? Wenn Ihr schon da draußen seid, tut etwas Sinnvolles und tötet diese verdammten Flohsäcke.", sourceObjective = "Tötet 5 Blutfangworgen.", completion = "Wenn ich nicht selbst gesehen hätte, dass Ihr ein paar von diesen verlausten Kötern getötet habt, hätte ich geschworen, dass Ihr Eure Aufgabe nicht erledigt habt.\n\nWir scheinen ihre Zahl nicht einmal annähernd dezimiert zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24931] = { id = 24931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starrermarke", description = "Ihr wollt Hyänen jagen, hm? Falls es Euch nicht stört, hätte ich selbst ein Angebot zu machen. Ich brauche die Augen von Glashautstarrern, die sich nördlich von hier befinden. Ihre Augen enthalten wundervolle Kristalle, die für... Sammler sehr viel wert sind.\n\nIhr habt vielleicht gehört, dass sie auch von manchen traurigen Gestalten zur Förderung der paramentalen Fähigkeiten genutzt werden, aber ich kann Euch versichern, dass mein Interesse rein akademischer Natur ist!\n\nBringt mir eine gute Ladung der Augen und ich werde Euch gut bezahlen. Zumindest besser als die Goblingeizkragen!", sourceObjective = "Sammelt 5 Okularkristalle von Glashautstarrern.", progress = "Ah, habt Ihr die Kristalle?", completion = "Aah, perfekt! Genau, was ich gebraucht habe... voller mächtiger, fokussierender Energien...\n\nÄhem! Ich meine natürlich sie sind ideal für meine Sammlung! Narain Pfauentraum braucht keine künstlichen Verbesserungen jeglicher Art!\n\nHier, nehmt Eure Bezahlung und geht nun!", sourceObjectiveStatus = "unverified-source-field" }
quests[24932] = { id = 24932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlust verhindern", description = "Seit einer Woche starre ich in diese eklige Grube in der Hoffnung, eine Idee zu bekommen, wie man diese gefährlichen, angriffslustigen Gliederfüßler gewinnbringend ausnutzen kann. Jetzt fällt mir nichts mehr ein und Hunger habe ich auch.\n\nDiese Dinger sind gefährlich und es ist an der Zeit, sie auszumerzen. Geht in die Grube und tötet das Ungeziefer.", sourceObjective = "Tötet 15 Silithiden der Hazzali jeglicher Art in der Klaffenden Schlucht.", completion = "Das dauert zu lange. Es muss eine schnellere Methode geben...", sourceObjectiveStatus = "unverified-source-field" }
quests[24933] = { id = 24933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnchen der Wüste", description = "Ich habe eine Idee, aber wir brauchen zuerst einen Köder.\n\nLetztens habe ich eine tollwütige Eiterpfotenhyäne gesehen, die nahe bei der Schlucht herumwanderte; plötzlich kam ein Silithid aus dem Nichts und hat sie fast in einem Haps verschlungen! War kein schöner Anblick.\n\nWir brauchen also ganz offensichtlich Hyänenfleisch. Bringt mir frisches Hyänenfleisch. Nördlich des Lagers solltet Ihr genügend Hyänen dafür finden.", sourceObjective = "Sammelt 6 Stücke Hyänenfleisch.", progress = "Das ist frisches Fleisch, ja? Um etwas, dass in der Sonne ausgetrocknet wurde, werden sie sich nicht reißen.", completion = "Man, das Zeug sieht lecker aus. Ich hätte fast Lust, für mich selber etwas davon zu braten.\n\nNein! Wir müssen uns darauf konzentrieren, hier wegzukommen.\n\nAber vielleicht doch ein kleines Stückchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24934] = { id = 24934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft Enternde von Bord!", description = "{name}, das Meer ist unsere Lebenslinie und gerade jetzt läuft der überwiegende Teil meiner Flotte mit voller Kraft zurück nach Theramore für Reparaturen oder rostet auf dem Grund dieser Bucht. Nur die Schwarzborn hält sich noch über Wasser, um unseren Hafen zu verteidigen.\n\nAber sie hat gerade Signale gesendet, dass sie geentert wird!\n\nSprecht mit mir, wenn Ihr bereit seid. Ich werde dafür sorgen, dass einer unserer Seegreife Euch auf Deck absetzt. Tötet die Seebären von Donnerschrei, die es wagen, mein kostbares Schiff anzugreifen und meldet Euch bei Kapitän Fischer für weitere Befehle.", sourceObjective = "Sprecht mit Admiral Aubrey, um zur Schwarzborn zu fliegen. Tötet dort 6 Seebären von Donnerschrei.", completion = "Ihr würdet einen verdammt guten Seemann abgeben, {name}.\n\nWir würden mit den anderen den Boden aufwischen. Aber wie es aussieht, zieht die Flotte der Horde sich aus dem Kampf zurück - vielleicht wollen sie noch mehr Truppen an Land absetzen?\n\nAdmiral Aubrey wird wissen, was zu tun ist. Sprecht mit mir, wenn Ihr bereit seid, zurückzufliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24937] = { id = 24937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot ist erledigt", description = "{name}, Ihr müsst zurück nach Instastadt und die Einwohner vor den Goblinzombies in der Caldera des Vulkans warnen!", sourceObjective = "Sprecht mit Sassy Hartzang in Instastadt auf den Verlorenen Inseln.", completion = "Sie haben ein paar von uns in Zombies verwandelt? Erzählt mir etwas Neues…", sourceObjectiveStatus = "unverified-source-field" }
quests[24938] = { id = 24938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kanonen von Nordwacht", description = "Kapitän Fischer hat uns von unten Signale gesendet. Die Flotte der Horde setzt Landmannschaften ab? Wir können nicht zulassen, dass sie uns vom Strand aus in die Flanke fallen.\n\nIch habe bereits zwei meiner besten Schützen dort hinuntergeschickt, um den Landeplatz zu verteidigen. Sprecht unten am Strand mit Kanonier Hecksler.\n\nIhr müsst Euch den Weg durch den Hof freikämpfen, um dorthin zu gelangen. Seht, ob Ihr auf dem Weg nach unten den anderen dabei helfen könnt, die Feste zu sichern.", sourceObjective = "Sprecht mit Kanonier Hecksler.", completion = "Aubrey hat Euch geschickt? Gut! Ich nehme an, Ihr wisst, wie Ihr mit einer Kanone umzugehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24939] = { id = 24939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt die Kanonen zum Einsatz", description = "Wir haben das Material, aber uns fehlen die Leute, {name}. Bemannt eins der Geschütze hier am Strand und schießt die ankommenden Boote ab!", sourceObjective = "Benutzt ein Küstengeschütz der Nordwacht um 10 Ruderboote von Donnerschrei zu zerstören.", completion = "Har har! Der Strand gehört uns!\n\nVielleicht schaffen wir es ja doch, uns auf diesem miesen Staubball von einem Kontinent zu behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24940] = { id = 24940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Vulkan", description = "Ein Haufen unserer Leute ist auf dem Weg zur Spitze des Vulkans, um eine Rettungsaktion und Gegenoffensive zu starten. Dort auf dem Verlorenen Gipfel braut sich etwas Schreckliches zusammen.\n\nSie warten auf Euch, bevor sie etwas gegen die Pygmäen unternehmen. Wie Ihr seht ist es diesen fiesen kleinen Wesen gelungen, viele von uns in Zombies zu verwandeln.\n\nRettet uns, {name}!", sourceObjective = "Sprecht mit Trainer Blutgrätsch auf dem Verlorenen Gipfel auf den Verlorenen Inseln.", completion = "Mein Spitzenspieler ist eingetroffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24941] = { id = 24941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langridges Munition", description = "{class}! Dem Licht sei Dank - sie haben uns fast bis zu den Docks zurückgeschlagen. Der Hof ist überrannt!\n\nWir haben keine Splittergranaten mehr und die Orcs bereiten sich auf einen Sturmangriff den Hügel hinauf vor. Wir müssen irgendwie Streumunition improvisieren - und das schnell.\n\nBeeilt Euch, rennt in den kaputten Turm hier und greift Euch allen scharfen und spitzen Metallschrott dessen Ihr habhaft werden könnt. Messer, Gabeln, Nägel - alles! Ladet die Kanone, sobald ihr einen Arm voll davon habt.", sourceObjective = "Sammelt 15 Stücke Langridges Munition.", progress = "Paxton hat bereits eine Ladung in die Kanone gestopft. Jetzt brauchen wir nur noch die improvisierte Munition.", completion = "Die Horde versammelt sich am Fuß des Hügels. Atemlos stopft Ihr die Trümmer, die Ihr aufgesammelt habt, in die Öffnung der Kanone, tretet zurück, haltet Euch ein Ohr zu und zerrt an der Zündschnur...", sourceObjectiveStatus = "unverified-source-field" }
quests[24942] = { id = 24942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombies gegen Superträgerraketenstiefel", description = "Diese Zombies, die an uns vorbeigekommen sind, sind nichts im Vergleich zu den Massen, die hinter dem Pass auf uns warten. Wenn wir uns nicht bald um sie kümmern, werden die Hexendoktoren der Pygmäen sie auf die Stadt hetzen. Selbst unsere Kanonen können gegen diese Mengen nichts ausrichten.\n\nIch konnte ein paar Schredderstiefel mit hierher bringen. Greely hat sie überarbeitet und jetzt sind es Superträgerraketenstiefel!\n\nVerwendet die Stiefel, um die Zombies in den Dörfern von Oostan im Osten in Flammen zu setzen.", sourceObjective = "Benutzt die Superträgerraketenstiefel, um 50 Goblinzombies zu töten.", progress = "Da warten noch ein paar Goblinzombies auf Euch, {name}. Immer die Ohren steif halten, Superstar!", completion = "Ihr habt es geschafft! Jetzt müssen wir uns nie mehr um Zombies sorgen. Legen wir eine Schweigeminute für unsere stinkenden Verflossenen ein.\n\nOK, fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[24943] = { id = 24943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof zurückerobern", description = "So säubert man einen Hügel. Die Leichen wurden von Messern und Gabeln aufgespießt!\n\nDer Donnerschreiklan hat die Mauern durchbrochen, aber wir können diesen Kampf immer noch gewinnen. Geht zum Fuße des Hügels und helft unseren Männern, den Hof unten zu halten...", sourceObjective = "Tötet 10 Grunzer von Donnerschrei.", completion = "Großartige Arbeit! Wir haben sie in die Knie gezwungen, vielleicht lange genug, um unsere Verteidigungstruppen an Land zu bringen.\n\nVorausgesetzt, wir finden einen Weg, ihre Artillerie auszuschalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[24944] = { id = 24944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Kampf", description = "Dieser Kampf ist noch nicht vorüber, {class}. Noch lange nicht.\n\nEinige der Soldaten im Hof haben immer noch einen Lebenshauch in ihren Lungen. Wir können sie retten! Ich habe diese Lumpen in eine Kräuterarznei getaucht, auf die wir uns in Gilneas immer verlassen haben. Der Geruch ist furchtbar, aber dieser Umschlag kann sogar Tote erwecken.\n\nBenutzt diese Bandagen bei verwundeten Verteidigern unten im Hof und wir werden sehen, ob wir sie wieder kampftauglich machen können.", sourceObjective = "Benutzt die kräutergetränkten Bandagen bei 6 verwundeten Verteidigern.", progress = "Ich hoffe, Ihr habt genug Bandagen? Mein Nachschub an diesen Kräutern wurde abgeschnitten, als diese Ungeheuer mein geliebtes Gilneas geplündert haben.", completion = "Ein gleichmäßiger Strom laufender Verwundeter ist den Hügel hinaufgekommen, um sich bei mir zu melden, {name}. Ich nehme an, das war Euer Werk? Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[24945] = { id = 24945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei kleine Pygmäen", description = "Ich finde es ja toll, dass wir all diese Zombies töten und so, obwohl sie unsere Freunde und Verwandten sind. Aber meint Ihr nicht, dass wir uns auch um diese Pygmäen kümmern sollten, die sie erschaffen?\n\nIn den drei Dörfern von Oostan, Oostan-Nord, Oostan-Sor und Oostan-Ost, gibt es drei Hexendoktoren: Gaahl, Malmo und Teloch.\n\nKönntet Ihr Euch um sie kümmern? Ich habe keine Lust, ein Zombie zu werden!", sourceObjective = "Tötet Gaahl, Malmo und Teloch.", completion = "Puh, da fällt mir aber ein Stein vom Herzen. Endlich muss ich mich nicht mehr darum sorgen, dass neue Zombies hinter meinem Gehirn her sind!", sourceObjectiveStatus = "unverified-source-field" }
